var lat = __LAT__;
var lon = __LON__;
var utcOffset = 10;

var now = new Date();
var dayOfYear = Math.floor((now - new Date(now.getFullYear(),0,0)) / 86400000);

var decl = -23.45 * Math.cos(2 * Math.PI * (dayOfYear + 10) / 365);
var declRad = decl * Math.PI / 180;
var latRad = lat * Math.PI / 180;
var cosHA = -Math.tan(latRad) * Math.tan(declRad);
cosHA = Math.max(-1, Math.min(1, cosHA));
var haDeg = Math.acos(cosHA) * 180 / Math.PI;
var solarNoon = 12 - lon / 15 + utcOffset;
var sunriseHour = solarNoon - haDeg / 15;
var sunsetHour  = solarNoon + haDeg / 15;

var windowOpen  = sunriseHour + 2;
var windowClose = sunsetHour  - 2;

var currentHour = now.getHours() + now.getMinutes() / 60;
var inWindow = (currentHour >= windowOpen && currentHour < windowClose);

var isTimeCheck = (msg.topic === "time_check");
var soc;

if (isTimeCheck) {
    soc = flow.get("lastSoc") || 0;
} else {
    soc = msg.payload;
    if (typeof soc !== "number") { return null; }
    flow.set("lastSoc", soc);
}

var hwState = flow.get("hwState") || "off";
var newState = hwState;

if (soc <= 90) {
    newState = "off";
} else if (!inWindow) {
    newState = "off";
} else if (soc >= 95 && inWindow) {
    newState = "on";
}

// Belt-and-braces safeguard: on every 5-min time check, if outside window,
// send an unconditional OFF command regardless of remembered hwState.
if (isTimeCheck && !inWindow) {
    flow.set("hwState", "off");
    var safeCmd  = { payload: { dps: 1, set: false } };
    var safeLog  = {
        payload: "[" + now.toLocaleTimeString("en-AU") + "] Hot Water OFF (safeguard: outside window)" +
                 " | Window: " + windowOpen.toFixed(1) + "-" + windowClose.toFixed(1)
    };
    return [safeCmd, safeLog];
}

if (newState !== hwState) {
    flow.set("hwState", newState);
    var cmd = { payload: { dps: 1, set: (newState === "on") } };
    var reason = isTimeCheck ? "window close" : "SOC=" + soc + "%";
    var logMsg = {
        payload: "[" + now.toLocaleTimeString("en-AU") + "] Hot Water " +
                 newState.toUpperCase() + " (" + reason + ")" +
                 " | Window: " + windowOpen.toFixed(1) + "-" + windowClose.toFixed(1)
    };
    return [cmd, logMsg];
}

return [null, null];

