const STALE_MS = 5 * 60 * 1000;
const SOURCES = ['pv_dc','pv_fronius','ac_load','soc','batt_power','plug_state','plug_power',
  'mppt288_state','mppt288_power','mppt289_state','mppt289_power',
  'mppt_x288_state','mppt_x288_power','mppt_x289_state','mppt_x289_power',
  'mode_288','mode_289','mode_rs1','mode_rs2'];

function num(x) {
  if (typeof x === 'number' && isFinite(x)) return x;
  if (x && typeof x.value === 'number' && isFinite(x.value)) return x.value;
  var n = parseFloat(x);
  return isFinite(n) ? n : null;
}

var t = msg.topic;
if (SOURCES.indexOf(t) !== -1) {
  var cache = flow.get('agg_cache') || {};
  var entry = { ts: Date.now() };
  if (t === 'plug_state') {
    var p = msg.payload;
    if (p && typeof p === 'object' && p.dps && (p.dps['1'] !== undefined)) entry.value = !!p.dps['1'];
    else entry.value = (p === true || p === 'true' || p === 1);
  } else if (t === 'plug_power') {
    var p2 = msg.payload;
    if (p2 && typeof p2 === 'object' && p2.dps && p2.dps['19'] !== undefined) entry.value = Number(p2.dps['19']) / 10;
    else { var v = num(p2); if (v === null) return null; entry.value = v; }
  } else {
    var v2 = num(msg.payload);
    if (v2 === null) return null;
    entry.value = v2;
  }
  cache[t] = entry;
  flow.set('agg_cache', cache);
  return null;
}

if (t === 'tick') {
  var cache2 = flow.get('agg_cache') || {};
  var now = Date.now();
  var stale = {};
  // Defaults for downstream — INCLUDING 'present' flags for the MPPT subs
  var state = {
    pv_dc: 0, pv_fronius: null, ac_load: 0, soc: -1, batt_power: 0,
    plug_state: false, plug_power: 0,
    // null defaults so dispatcher can detect 'no data yet'
    mppt288_power: null, mppt288_state: null,
    mppt289_power: null, mppt289_state: null,
    mppt_x288_power: null, mppt_x288_state: null,
    mppt_x289_power: null, mppt_x289_state: null,
    mode_288: null, mode_289: null, mode_rs1: null, mode_rs2: null,
    ts: now, stale: stale
  };
  SOURCES.forEach(function(k){
    var e = cache2[k];
    if (!e || (now - e.ts) > STALE_MS) { stale[k] = true; }
    if (e && e.value !== undefined && e.value !== null) state[k] = e.value;
  });
  return { topic: 'state', payload: state };
}
return null;

// HOT WATER v3+ — SIMPLIFIED + HEURISTIC + MPPT-AWARE CURTAILMENT
// 2026-06-02 PM revisions:
//   - removed cylinder_done, post-OFF cooldown, plug-telemetry stale gates
//   - heuristic curtailment override (SOC≥85 AND batt_power ∈ [0,500])
//   - MPPT-aware curtailment: BlueSolar 258 or 259 yield < 200W AND SOC ≥ 80
//   - When mpptCurtailed: SURPLUS_OFF threshold lowered 1200→300, sustain 60→180s
//     (give the BlueSolars time to ramp up when HW element fires)

const SURPLUS_ON_W           = __DISP_SURPLUS_ON_W__;
const SURPLUS_OFF_W          = __DISP_SURPLUS_OFF_W__;
const SURPLUS_OFF_W_CURT     = __DISP_SURPLUS_OFF_W_CURT__;        // lowered while MPPT-curtailed
const SUSTAIN_OFF_MS         = __DISP_SUSTAIN_OFF_MS__;
const SUSTAIN_OFF_MS_CURT    = __DISP_SUSTAIN_OFF_MS_CURT__;     // extended while MPPT-curtailed
const ELEMENT_W              = __DISP_ELEMENT_W__;
const AC_CAP_W               = __DISP_LOAD_CAP_W__;
const AC_SAFETY_W            = __DISP_SAFETY_CAP_W__;
var SOC_ON_PCT             = __DISP_W1_SOC_ON__;
var SOC_OFF_PCT            = __DISP_W1_SOC_OFF__;
const SUSTAIN_ON_MS          = __DISP_SUSTAIN_ON_MS__;
const STALE_TOPIC_FAIL_OPEN  = true;
// Heuristic curtailment (battery-near-full)
const CURTAIL_SOC_PCT        = 85;
const CURTAIL_BATT_LOW_W     = 0;
const CURTAIL_BATT_HIGH_W    = 1500;
const CURTAIL_FRONIUS_W      = __DISP_CURTAIL_FRONIUS_W__;    // v3.1 2026-06-04 Steven: Fronius < this W = freq-shift throttled
// MPPT-aware curtailment (BlueSolars idle while Multi RS meets demand)
const MPPT_IDLE_W            = 200;        // per-BlueSolar yield below this = idle/throttled
const MPPT_CURT_SOC_PCT      = 80;
const MPPT_CURT_MIN_OTHER_W  = 1000;      // RS+Fronius must produce >= this while BlueSolars idle = real curtailment (else just no sun)

function now() { return Date.now(); }
function iso() { return new Date().toISOString(); }
function num(x, d) { return (typeof x === 'number' && isFinite(x)) ? x : (d === undefined ? 0 : d); }
function emit(out, m) { var a=[null,null,null,null,null]; a[out]=m; return a; }
function emitMany(map) { var a=[null,null,null,null,null]; Object.keys(map).forEach(function(k){ a[+k]=map[k]; }); return a; }
function logPayload(eventName, extra) { return { topic:'bsf/hotwater/log', payload: Object.assign({ ts:iso(), event:eventName }, extra||{}) }; }
function statusPayload(extra) { return { topic:'bsf/hotwater/status', payload: Object.assign({ ts:iso() }, extra||{}) }; }
function anomalyPayload(reason, extra) { return { topic:'bsf/hotwater/anomaly', payload: Object.assign({ ts:iso(), reason:reason, source:'dispatcher' }, extra||{}) }; }
function plugCmd(on) { return { payload: { dps:'1', set:!!on } }; }

if (msg.topic === 'daily_summary') {
  var c = context.get('counters') || {};
  var openStarted = context.get('onStartedAt') || 0;
  if (openStarted) { c.on_minutes = num(c.on_minutes,0) + (Date.now()-openStarted)/60000; context.set('onStartedAt', Date.now()); }
  var onMin = num(c.on_minutes, 0);
  var lockoutAnomaliesToday = flow.get('lockout_anomalies') || 0;
  var summary = { topic:'bsf/hotwater/daily', payload: {
    ts:iso(), date_local:new Date().toLocaleDateString('en-AU'),
    on_minutes:+(onMin.toFixed(1)), on_kwh:+((onMin/60*(ELEMENT_W/1000)).toFixed(3)),
    on_transitions:num(c.on_transitions,0), off_transitions:num(c.off_transitions,0),
    curtailment_on_hits:num(c.curtailment_on_hits,0), mppt_curtailment_holds:num(c.mppt_curtailment_holds,0),
    safety_trips:num(c.safety_trips,0), lockout_anomalies:lockoutAnomaliesToday,
    last_on:c.last_on||null, last_off:c.last_off||null
  } };
  context.set('counters', {}); flow.set('lockout_anomalies', 0);
  return emit(4, summary);
}

if (msg.topic !== 'state') return null;

var s = msg.payload || {};
var t = now();

var sunriseISO = flow.get('sunrise');
var sunsetISO  = flow.get('sunset');
var sunrise = sunriseISO ? Date.parse(sunriseISO) : null;
var sunset  = sunsetISO  ? Date.parse(sunsetISO)  : null;
if (!sunrise || !sunset || isNaN(sunrise) || isNaN(sunset)) {
  var d = new Date();
  sunrise = new Date(d.getFullYear(),d.getMonth(),d.getDate(),6,0,0).getTime();
  sunset  = new Date(d.getFullYear(),d.getMonth(),d.getDate(),18,0,0).getTime();
  node.warn('dispatcher: no sunrise/sunset, fallback 06-18');
}
var DISPATCH_END_OFFSET_MS = 2 * 60 * 60 * 1000;
var mode = (t >= sunrise && t < (sunset - DISPATCH_END_OFFSET_MS)) ? 'DISPATCH' : 'LOCKOUT';
flow.set('mode', mode);
var _hwHourFrac = new Date(t).getHours() + new Date(t).getMinutes()/60;
var hwWindow = 'W1';
if (_hwHourFrac >= 8.0 && _hwHourFrac < 13.0) {
    SOC_ON_PCT = __DISP_W2_SOC_ON__; SOC_OFF_PCT = __DISP_W2_SOC_OFF__; hwWindow = 'W2';
} else if (_hwHourFrac >= 13.0 && t < (sunset - DISPATCH_END_OFFSET_MS)) {
    SOC_ON_PCT = __DISP_W3_SOC_ON__; SOC_OFF_PCT = __DISP_W3_SOC_OFF__; hwWindow = 'W3';
}
flow.set('hw_window', hwWindow);
var hwState         = context.get('hwState')         || 'off';
var surplusOnSince  = context.get('surplusOnSince')  || null;
var surplusOffSince = context.get('surplusOffSince') || null;
var counters        = context.get('counters')        || {};

// Stale check — Cerbo telemetry only
var stale = s.stale || {};
var anyStale = false; var staleList = [];
['pv_dc','pv_fronius','ac_load','soc'].forEach(function(k){ if (stale[k]) { anyStale=true; staleList.push(k); } });

var pv_total   = num(s.pv_dc) + num(s.pv_fronius);
var ac_load    = num(s.ac_load);
var soc        = num(s.soc, -1);
var batt_power = num(s.batt_power);
var plug_state = !!s.plug_state;
var plug_power = num(s.plug_power);
var ac_other   = plug_state ? Math.max(0, ac_load - plug_power) : ac_load;
var surplus_now      = pv_total - ac_other;
var surplus_after_on = surplus_now - ELEMENT_W;
var ac_after_on      = ac_other + ELEMENT_W;
// Resolve which MPPT instance pair has data (258/259 OR 288/289)
var mA = (typeof s.mppt288_power === 'number') ? s.mppt288_power : ((typeof s.mppt_x288_power === 'number') ? s.mppt_x288_power : null);
var mB = (typeof s.mppt289_power === 'number') ? s.mppt289_power : ((typeof s.mppt_x289_power === 'number') ? s.mppt_x289_power : null);
var mAState = s.mppt288_state || s.mppt_x288_state || null;
var mBState = s.mppt289_state || s.mppt_x289_state || null;
var mppt288_power = mA;
var mppt289_power = mB;
var mppt288_state = mAState;
var mppt289_state = mBState;
// mppt_curtailed requires ACTUAL data (numeric); both null = no subscribers firing = don't trust
var mpptDataValid = (typeof mA === 'number') && (typeof mB === 'number');
var anyMpptIdle = mpptDataValid && ((mA < MPPT_IDLE_W) || (mB < MPPT_IDLE_W));
var mppt_other_pv = pv_total - num(mA) - num(mB);   // RS + Fronius (pv_dc already includes the BlueSolars)
var mppt_curtailed = anyMpptIdle && (soc >= MPPT_CURT_SOC_PCT) && (mppt_other_pv >= MPPT_CURT_MIN_OTHER_W);
var curtailed_heuristic = (soc >= CURTAIL_SOC_PCT) && (batt_power >= CURTAIL_BATT_LOW_W) && (batt_power < CURTAIL_BATT_HIGH_W);
var fronius_curtailed = (soc >= CURTAIL_SOC_PCT) && (batt_power >= CURTAIL_BATT_LOW_W) && Number.isFinite(s.pv_fronius) && (s.pv_fronius < CURTAIL_FRONIUS_W);
// ↑ legacy heuristics RETAINED FOR OBSERVABILITY/COMPARISON ONLY — they NO LONGER drive `curtailed` (2026-06-16, Steven).
// CANONICAL CURTAILMENT: Victron hardware MppOperationMode throttle state, OR'd across all 4 DC PV trackers.
//   0=Off, 1=Voltage/current limited (THROTTLED = real curtailment), 2=MPPT active, 255=N/A.
var mode_288 = (typeof s.mode_288 === 'number') ? s.mode_288 : null;
var mode_289 = (typeof s.mode_289 === 'number') ? s.mode_289 : null;
var mode_rs1 = (typeof s.mode_rs1 === 'number') ? s.mode_rs1 : null;
var mode_rs2 = (typeof s.mode_rs2 === 'number') ? s.mode_rs2 : null;
var curtailed = (mode_288 === 1) || (mode_289 === 1) || (mode_rs1 === 1) || (mode_rs2 === 1);

// When curtailed, use relaxed OFF threshold + extended sustain
var off_thresh = curtailed ? SURPLUS_OFF_W_CURT : SURPLUS_OFF_W;
var off_sust   = curtailed ? SUSTAIN_OFF_MS_CURT : SUSTAIN_OFF_MS;

var statusMsg = statusPayload({
  mode:mode, hwState:hwState, soc:soc,
  pv_total:pv_total, ac_load:ac_load, ac_other:ac_other, plug_power:plug_power,
  batt_power:batt_power,
  surplus_now:Math.round(surplus_now), surplus_after_on:Math.round(surplus_after_on),
  ac_after_on:Math.round(ac_after_on),
  curtailed:curtailed, curtailed_heuristic:curtailed_heuristic, fronius_curtailed:fronius_curtailed, mppt_curtailed:mppt_curtailed, mppt_other_pv:Math.round(mppt_other_pv),
  mode_288:mode_288, mode_289:mode_289, mode_rs1:mode_rs1, mode_rs2:mode_rs2,
  mppt288_state:mppt288_state, mppt288_power:Math.round(mppt288_power),
  mppt289_state:mppt289_state, mppt289_power:Math.round(mppt289_power),
  off_thresh_active:off_thresh, off_sustain_active:off_sust,
  sunrise_iso:sunriseISO, sunset_iso:sunsetISO, stale:staleList
});

function accrueOnMinutes() {
  var started = context.get('onStartedAt') || 0;
  if (started) counters.on_minutes = num(counters.on_minutes,0) + (t-started)/60000;
  context.set('onStartedAt', 0);
}
function tripOff(eventName, reason, classTag) {
  accrueOnMinutes();
  counters.off_transitions = num(counters.off_transitions,0)+1;
  if (classTag === 'safety') counters.safety_trips = num(counters.safety_trips,0)+1;
  counters.last_off = iso();
  context.set('counters', counters);
  context.set('hwState', 'off');
  context.set('surplusOnSince', null);
  context.set('surplusOffSince', null);
  var outs = { 0:plugCmd(false), 1:logPayload(eventName, {reason:reason, soc:soc, surplus:Math.round(surplus_now), batt_power:Math.round(batt_power), curtailed:curtailed, mppt288_power:Math.round(mppt288_power), mppt289_power:Math.round(mppt289_power), ac:ac_load}), 2:statusMsg };
  if (classTag === 'safety') outs[3] = anomalyPayload(reason, {soc:soc, ac:ac_load, surplus:Math.round(surplus_now)});
  return emitMany(outs);
}

if (anyStale && STALE_TOPIC_FAIL_OPEN) {
  if (hwState === 'on') return tripOff('off_topic_stale', 'stale: '+staleList.join(','), 'safety');
  return emitMany({ 2: statusMsg });
}
if (soc >= 0 && soc < SOC_OFF_PCT) {
  if (hwState === 'on') return tripOff('off_soc_floor', 'SOC '+soc+'% < '+SOC_OFF_PCT+'%', 'safety');
  return emitMany({ 2: statusMsg });
}
if (ac_load > AC_SAFETY_W) {
  if (hwState === 'on') return tripOff('off_ac_cap', 'ac_load '+Math.round(ac_load)+'W > '+AC_SAFETY_W+'W', 'safety');
  return emitMany({ 2: statusMsg });
}

if (mode === 'LOCKOUT') {
  if (hwState === 'on') return tripOff('off_mode_lockout', 'mode→LOCKOUT', 'lifecycle');
  return emitMany({ 2: statusMsg });
}

// DISPATCH — OFF eval (relaxed during curtailment)
if (hwState === 'on') {
  if (surplus_now <= off_thresh) {
    if (!surplusOffSince) { surplusOffSince = t; context.set('surplusOffSince', t); }
    if ((t - surplusOffSince) >= off_sust) {
      var reasonStr = 'surplus ' + Math.round(surplus_now) + 'W ≤ ' + off_thresh + 'W (' + (curtailed ? 'mppt_curtailed='+mppt_curtailed+' heuristic_curtailed='+curtailed_heuristic+' relaxed' : 'not curtailed') + ', sustain ' + off_sust/1000 + 's)';
      return tripOff('off_surplus', reasonStr, 'normal');
    } else if (curtailed) {
      counters.mppt_curtailment_holds = num(counters.mppt_curtailment_holds,0) + 1;
      context.set('counters', counters);
    }
  } else {
    if (surplusOffSince) context.set('surplusOffSince', null);
  }
  return emitMany({ 2: statusMsg });
}

// hwState === 'off' — evaluate ON
var surplusOk = (surplus_now >= SURPLUS_ON_W) || (curtailed && soc >= SOC_ON_PCT);
var pointGates = { surplus_ok: surplusOk, ac_ok: ac_after_on <= AC_CAP_W, soc_ok: soc >= SOC_ON_PCT };
var allOk = Object.keys(pointGates).every(function(k){ return pointGates[k]; });

if (allOk) {
  if (!surplusOnSince) { surplusOnSince = t; context.set('surplusOnSince', t); }
  if ((t - surplusOnSince) >= SUSTAIN_ON_MS) {
    counters.on_transitions = num(counters.on_transitions,0)+1;
    if (curtailed) counters.curtailment_on_hits = num(counters.curtailment_on_hits,0)+1;
    counters.last_on = iso();
    context.set('counters', counters);
    context.set('hwState', 'on');
    context.set('onStartedAt', t);
    context.set('surplusOnSince', null);
    context.set('surplusOffSince', null);
    var eventName = curtailed ? 'on_curtailment' : 'on_surplus';
    return emitMany({
      0: plugCmd(true),
      1: logPayload(eventName, {surplus:Math.round(surplus_now), surplus_after_on:Math.round(surplus_after_on), soc:soc, ac:ac_load, batt_power:Math.round(batt_power), curtailed:curtailed, curtailed_heuristic:curtailed_heuristic, mppt_curtailed:mppt_curtailed, mppt288_power:Math.round(mppt288_power), mppt289_power:Math.round(mppt289_power)}),
      2: statusMsg
    });
