function aestISO(h, m) {
  var nowAest = new Date(Date.now() + 10*3600*1000);
  var y = nowAest.getUTCFullYear();
  var mo = nowAest.getUTCMonth();
  var d = nowAest.getUTCDate();
  return new Date(Date.UTC(y, mo, d, h - 10, m, 0)).toISOString();
