var ssISO = aestISO(17, 30);
flow.set('sunrise', srISO);
flow.set('sunset',  ssISO);
return { topic: 'bsf/hotwater/log', payload: { ts: new Date().toISOString(), event: 'sunrise_cron_temp_patch', sunrise: srISO, sunset: ssISO, note: 'fixed 05:30-17:30 AEST until astronomical algorithm is corrected' } };

// =============================================================
// HOT WATER v3 — LOCKOUT LOOP (function node, 3 outputs)
//
// Banksia Springs Farm — written 2026-06-01.
// Plan: ~/Documents/wikis/bsf/hot-water-v3-dispatch-plan.md §5
//
// PURPOSE
//   Fires every 5 minutes from an inject node (cron "*/5 * * * *").
//   Independent of the dispatcher so it works even if the dispatcher
//   is wedged or restarting.
//
//   If mode === "LOCKOUT" (i.e. we're outside today's sunrise/sunset
//   window): publish OFF to the plug, unconditionally. If the plug
//   appears to be ON when we run, also emit an anomaly event — that's
