//
// OUTPUTS
//   [0] plug_cmd       — { payload: {dps:"1", set:false} } (only in LOCKOUT)
//   [1] log_event      — { topic:"bsf/hotwater/log", payload:{...} }
//   [2] anomaly_event  — { topic:"bsf/hotwater/anomaly", payload:{...} }
//                        only when plug was found ON during lockout
// =============================================================

function iso() { return new Date().toISOString(); }
function plugOff() { return { payload: { dps: "1", set: false } }; }

var mode = flow.get("mode");

// Read the aggregator's cache directly so we don't depend on the
// dispatcher being alive. We just want plug_state to flag anomalies.
var cache = flow.get("agg_cache") || {};
var plugEntry = cache.plug_state;
var plugState = plugEntry ? !!plugEntry.value : null;
var plugStale = (!plugEntry || (Date.now() - plugEntry.ts) > (5 * 60 * 1000));

// Fail-safe: if mode is undefined (dispatcher hasn't run yet, e.g.
// Cerbo just rebooted, MQTT not flowing), assume LOCKOUT. Cheaper to
// fire a spurious OFF than to leave the plug uncontrolled.
if (mode === undefined || mode === null) { mode = "LOCKOUT"; }

if (mode !== "LOCKOUT") {
    // Dispatch mode: do nothing. We don't even log — too noisy.
    return null;
}

// LOCKOUT. Force OFF unconditionally.
var foundOn = (plugState === true);

// Bookkeeping for the daily summary. Function nodes have their own
// context; we share with the dispatcher via flow.lockout_anomalies,
// which the dispatcher reads at 23:00 and resets.
var lockoutAnomalies = flow.get("lockout_anomalies") || 0;
if (foundOn) {
    lockoutAnomalies++;
    flow.set("lockout_anomalies", lockoutAnomalies);
}

var logMsg = {
    topic: "bsf/hotwater/log",
    payload: {
        ts: iso(),
        event: "lockout_force_off",
        plug_state_at_check: plugState,
        plug_state_stale: plugStale,
        found_on: foundOn,
        anomaly_count_today: lockoutAnomalies
    }
};

var outs = [ plugOff(), logMsg, null ];

if (foundOn) {
    outs[2] = {
        topic: "bsf/hotwater/anomaly",
        payload: {
            ts: iso(),
            reason: "plug ON during LOCKOUT — likely manual button press or input desync",
            source: "lockout_loop",
            plug_state_at_check: plugState,
            anomaly_count_today: lockoutAnomalies
        }
    };
    node.warn("lockout: plug found ON outside window — forcing OFF. count today=" + lockoutAnomalies);
}

return outs;

if (msg.payload && msg.payload.data && msg.payload.data.dps && msg.payload.data.dps["19"] !== undefined) {
