const CLIENT_ID = '__TUYA_ACCESS_ID__';
const SECRET = '__TUYA_ACCESS_SECRET__';
const BASE_HOST = '__TUYA_API_HOST__';
const AC_DEV_ID = '__TUYA_DEVICE_AC__';

const sha256 = s => crypto.createHash('sha256').update(s||'').digest('hex');
const hmac = (k,s) => crypto.createHmac('sha256',k).update(s).digest('hex').toUpperCase();

function httpJson(method, path, headers, bodyStr) {
  return new Promise((resolve) => {
    const opts = {hostname: BASE_HOST, port: 443, path, method, headers, timeout: 10000};
    const req = https.request(opts, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve({status: res.statusCode, json: JSON.parse(data)}); } catch(e) { resolve({status: res.statusCode, raw: data}); } });
    });
    req.on('error', e => resolve({error: e.message}));
    req.on('timeout', () => { req.destroy(); resolve({error:'timeout'}); });
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

async function fetchToken() {
  const t = Date.now();
  const path = '/v1.0/token?grant_type=1';
  const ss = 'GET\n' + sha256('') + '\n\n' + path;
  const sign = hmac(SECRET, CLIENT_ID + t + ss);
  const r = await httpJson('GET', path, {client_id: CLIENT_ID, sign, sign_method: 'HMAC-SHA256', t: String(t)}, null);
  if (!r.json || !r.json.success) throw new Error('token: ' + JSON.stringify(r).slice(0,200));
  flow.set('tuya_token', r.json.result.access_token);
  flow.set('tuya_token_exp', Date.now() + (r.json.result.expire_time - 60) * 1000);
  return r.json.result.access_token;
}

async function getToken() {
  let token = flow.get('tuya_token');
  if (!token || Date.now() >= (flow.get('tuya_token_exp') || 0)) token = await fetchToken();
  return token;
}

async function signedCall(method, path, body) {
  const token = await getToken();
  const t = Date.now();
  const bodyStr = body ? JSON.stringify(body) : '';
  const ss = method + '\n' + sha256(bodyStr) + '\n\n' + path;
  const sign = hmac(SECRET, CLIENT_ID + token + t + ss);
  const headers = {client_id: CLIENT_ID, access_token: token, sign, sign_method: 'HMAC-SHA256', t: String(t)};
  if (body) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = Buffer.byteLength(bodyStr); }
  return await httpJson(method, path, headers, body ? bodyStr : null);
}

// === Input handling ===
const p = msg.payload || {};
const deviceId = msg.tuya_device_id || AC_DEV_ID;

// Status query mode: msg.payload = {query: 'status'} (or msg.tuya_query='status')
if (p.query === 'status' || msg.tuya_query === 'status') {
  try {
    const r = await signedCall('GET', '/v1.0/iot-03/devices/' + deviceId + '/status', null);
    msg.payload = r;
    flow.set('cs_last_status', JSON.stringify(r).slice(0,800));
  } catch (e) { msg.payload = {error: String(e)}; }
  return msg;
}

// Command mode
let commands;
if (Array.isArray(p.commands)) commands = p.commands;
else if (p.dps !== undefined && p.set !== undefined) commands = [{code: 'switch_' + p.dps, value: !!p.set}];
else { flow.set('cs_last_error', 'unrecognised: ' + JSON.stringify(p)); return msg; }

// === Idempotency: skip if last sent command identical ===
const cmdKey = deviceId + '|' + JSON.stringify(commands);
const lastKey = flow.get('cs_last_cmdkey');
const lastAt = flow.get('cs_last_cmdkey_at') || 0;
// Only skip if same command sent within last 60s AND last result was success
if (cmdKey === lastKey && (Date.now() - lastAt) < 600000 && flow.get('cs_last_success')) {
  flow.set('cs_skipped', (flow.get('cs_skipped')||0) + 1);
  msg.payload = {skipped: true, reason: 'duplicate within 60s', commands};
  return msg;
}

const c = (flow.get('cs_invocations')||0) + 1;
flow.set('cs_invocations', c);
flow.set('cs_last_run', new Date().toISOString());
flow.set('cs_last_commands', JSON.stringify(commands));

try {
  const result = await signedCall('POST', '/v1.0/iot-03/devices/' + deviceId + '/commands', {commands});
  flow.set('cs_last_result', JSON.stringify(result).slice(0,500));
  const ok = !!(result.json && result.json.success);
  flow.set('cs_last_success', ok);
  if (ok) {
    flow.set('cs_last_cmdkey', cmdKey);
    flow.set('cs_last_cmdkey_at', Date.now());
  }
  msg.payload = result;
} catch (e) {
  flow.set('cs_last_error', String(e).slice(0,400));
  flow.set('cs_last_success', false);
  msg.payload = {error: String(e)};
}
return msg;

// tuya_poll_inside_temp — polls Tuya cloud for inside-temp-plug status, emits temp.
// Triggered by 60s inject. Uses libs: crypto, https.
// Output: { topic: 'inside_temp', payload: <celsius> } → mqtt out.

const API_KEY = '__TUYA_ACCESS_ID__';
const API_SECRET = '__TUYA_ACCESS_SECRET__';
const DEVICE_ID = '__TUYA_DEVICE_INSIDE__';
const HOST = '__TUYA_API_HOST__';

const EMPTY_SHA256 = crypto.createHash('sha256').update('').digest('hex');

function sign(secret, str) {
    return crypto.createHmac('sha256', secret).update(str).digest('hex').toUpperCase();
}

function makeNonce() {
    return crypto.randomBytes(8).toString('hex');
}

function tuyaGet(path, accessToken) {
    return new Promise(function(resolve, reject) {
        const t = Date.now().toString();
        const nonce = makeNonce();
        const stringToSign = 'GET\n' + EMPTY_SHA256 + '\n\n' + path;
        const signStr = accessToken
            ? API_KEY + accessToken + t + nonce + stringToSign
            : API_KEY + t + nonce + stringToSign;
        const signature = sign(API_SECRET, signStr);
        const headers = {
            client_id: API_KEY,
            sign: signature,
            sign_method: 'HMAC-SHA256',
            t: t,
            nonce: nonce,
        };
        if (accessToken) headers.access_token = accessToken;
        const req = https.request({
            hostname: HOST, path: path, method: 'GET', headers: headers, timeout: 8000,
        }, function(res) {
            let body = '';
            res.on('data', function(c) { body += c; });
            res.on('end', function() {
                try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
            });
        });
        req.on('error', reject);
        req.on('timeout', function() { req.destroy(new Error('timeout')); });
        req.end();
    });
}

(async function() {
    try {
        let token = flow.get('tuya_token');
        let tokenExp = flow.get('tuya_token_expires') || 0;
        const now = Date.now();
        if (!token || now > tokenExp) {
            const tr = await tuyaGet('/v1.0/token?grant_type=1', null);
            if (!tr.success) throw new Error('token: ' + (tr.msg || JSON.stringify(tr).substring(0,80)));
            token = tr.result.access_token;
            flow.set('tuya_token', token);
            flow.set('tuya_token_expires', now + (tr.result.expire_time - 60) * 1000);
        }
        const sr = await tuyaGet('/v1.0/devices/' + DEVICE_ID + '/status', token);
        if (!sr.success) throw new Error('status: ' + (sr.msg || JSON.stringify(sr).substring(0,80)));
        const tempDp = sr.result.find(function(dp) { return dp.code === 'va_temperature' || dp.code === 'temp_current' || dp.code === 'cur_temperature' || String(dp.code) === '18' || String(dp.code) === '8' || String(dp.code) === '101'; });
        if (!tempDp) throw new Error('no temp DP in: ' + JSON.stringify(sr.result).substring(0,200));
        const tempC = parseFloat(tempDp.value) / 10;
        flow.set('ac_inside_temp', tempC);
        flow.set('ac_inside_temp_ts', Date.now());
        node.status({ fill: 'green', shape: 'dot', text: tempC.toFixed(1) + '°C @ ' + new Date().toLocaleTimeString() });
    } catch (e) {
        node.error('Tuya poll failed: ' + e.message, msg);
        node.status({ fill: 'red', shape: 'dot', text: 'err: ' + e.message.substring(0, 40) });
    }
})();

return null;

// AC v1.10 — v1.9 + inside-temp gate (winter heating) (2026-06-05 Steven, v1.10)
// AC v1.11 — presence-aware AUTO/ON/OFF mode switch (2026-06-17 Steven)
//
// v1.8 fix: use plug_power > 100 W as the "HW is drawing" signal instead of the
// non-existent p.plug_state. HW dispatcher status publishes hwState (commanded)
// and plug_power (actual draw) but not plug_state. Using plug_power also handles
// the "cylinder hot, thermostat open" case correctly — no drawing = AC can run.
//
// Windows (local AEST):
//   W1: sunrise - 2 h  ->  08:00            ON SOC >= 80   OFF SOC < 75   (pre-heat; HW unlikely to fire this early)
//   W2: 08:00          ->  13:00             ON SOC >= 90   OFF SOC < 85   AND HW must not be drawing
//   W3: 13:00          ->  sunset - 2 h     ON SOC >= 99   OFF SOC < 98   AND HW must not be drawing
// Outside any window: OFF (5-min force-OFF loop keeps it OFF).
//
// Cascade safety:
//   If ac_load > AC_SAFETY_W (4200 W) AND HW is NOT drawing AND AC is ON,
//   AC dispatcher trips itself off. (HW dispatcher handles the same threshold first;
//   when HW dispatcher kills HW, plug_power drops to 0 and AC sees hwDrawing = false
//   on its next tick.)
//
// v1.11 (2026-06-17 Steven): AUTO / ON / OFF mode switch + LAN presence gate.
//   ac_mode (flow context, default 'AUTO'):
//     'OFF'  — HARD OVERRIDE. Force the plug OFF every tick; beats window, temp,
//              SOC, presence and manual ON. The most restrictive mode.
//     'ON'   — run the EXACT existing surplus-solar logic (window / SOC / temp /
//              cascade-safety), but presence-INDEPENDENT. "Heat when it's cold and
//              there's solar, whether or not the detector sees a phone."
//     'AUTO' — the same surplus-solar logic, additionally GATED on anyone_home:
//              heat only when someone is home. Nobody home -> force OFF.
//   anyone_home arrives on bsf/presence/state from the farm-iMac LAN presence
//   detector (bsf_presence.py). Presence is a COMFORT gate layered ON TOP of the
//   surplus-solar safety envelope — it NEVER bypasses SOC / window / lockout /
//   cascade-safety. A dead presence feed (no update for > PRESENCE_STALE_MS) fails
//   OPEN in AUTO (so a detector outage cannot strand the house cold); this is
//   surfaced as presence_known:false on the status. The detector already applies a
//   5-min "away" grace, so anyone_home will not flap on WiFi sleep/roam.
//   See dossiers/ac_presence_gate_2026-06-17.md
//
// Inputs:
//   msg.topic === 'tick'             — 30s tick from inject. State eval.
//   msg.topic === 'hw_status'        — HW dispatcher status payload (hwState, plug_power, soc, ac_load, sunrise/sunset).
//   msg.topic === 'lockout_tick'     — 5-min force-OFF outside any window.
//   msg.topic === 'inside_temp'      — Tuya cloud inside-temperature reading.
//   msg.topic === 'bsf/ac/cmd'       — dashboard command: set_thresholds | set_mode.
//   msg.topic === 'bsf/presence/state' — LAN presence detector (anyone_home).
//
// Outputs (4):
//   [0] plug command   [1] bsf/ac/log   [2] bsf/ac/status   [3] bsf/ac/anomaly

const W1_PRE_SUNRISE_OFFSET_MS = 2 * 60 * 60 * 1000;  // start 2 h before sunrise
const W1_END_H = 8.0;
const W2_END_H = 13.0;
const DISPATCH_END_OFFSET_MS = 2 * 60 * 60 * 1000;    // end W3 2 h before sunset

const W1_ON_PCT = __AC_W1_SOC_ON__, W1_OFF_PCT = __AC_W1_SOC_OFF__;
const W2_ON_PCT = __AC_W2_SOC_ON__, W2_OFF_PCT = __AC_W2_SOC_OFF__;
const W3_ON_PCT = __AC_W3_SOC_ON__, W3_OFF_PCT = __AC_W3_SOC_OFF__;

const SUSTAIN_ON_MS  = __AC_SUSTAIN_ON_MS__;
const SUSTAIN_OFF_MS = __AC_SUSTAIN_OFF_MS__;

const AC_SAFETY_W = __DISP_SAFETY_CAP_W__;             // cascade trip — fires only if HW is not currently drawing
const HW_DRAWING_THRESHOLD_W = 100;

// v1.10 (2026-06-05 Steven): inside-temperature gate (winter heating)
// v1.10.2 (2026-06-17 Steven): inside-temp thresholds promoted to FLOW CONTEXT so
// they can be tuned live from the dashboard (bsf/ac/cmd) with NO redeploy. Defaults
// preserve the v1.10 winter-heating values. See
// dossiers/ac_threshold_controls_2026-06-16.md
const INSIDE_TEMP_ON_DEFAULT  = __AC_INSIDE_ON_DEFAULT__;   // start heating when inside < this (degC)
const INSIDE_TEMP_OFF_DEFAULT = __AC_INSIDE_OFF_DEFAULT__;   // stop  heating when inside >= this (degC)
const INSIDE_TEMP_ON_MIN  = 16, INSIDE_TEMP_ON_MAX  = 26;   // sane heating-ON range
const INSIDE_TEMP_OFF_MIN = 18, INSIDE_TEMP_OFF_MAX = 28;   // sane heating-OFF range
const INSIDE_TEMP_MIN_GAP = 1.0;      // heating hysteresis: OFF must be >= ON + gap
const INSIDE_TEMP_STALE_MS = 10 * 60 * 1000;   // inside-temp feed older than this = unusable

// v1.11 (2026-06-17 Steven): presence feed freshness. Detector publishes every ~45s;
// no update for this long = feed dead -> AUTO fails OPEN (treat as someone home).
const PRESENCE_STALE_MS = 8 * 60 * 1000;

function clampStep(v, lo, hi){ v = Math.round(v * 2) / 2; if (v < lo) v = lo; if (v > hi) v = hi; return v; }
function getThresholds(){
    var on  = flow.get('ac_inside_temp_on_c');
    var off = flow.get('ac_inside_temp_off_c');
    if (typeof on  !== 'number' || !isFinite(on))  on  = INSIDE_TEMP_ON_DEFAULT;
    if (typeof off !== 'number' || !isFinite(off)) off = INSIDE_TEMP_OFF_DEFAULT;
    return { on: on, off: off };
}
function getMode(){
    var m = flow.get('ac_mode');
    if (m === 'AUTO' || m === 'ON' || m === 'OFF') return m;
    return 'AUTO';
}

function iso() { return new Date().toISOString(); }
function nowMs() { return Date.now(); }
function plugCmd(on) { return { payload: { dps: '1', set: !!on } }; }
function logPayload(event, extra) {
    return { topic: 'bsf/ac/log', payload: Object.assign({ ts: iso(), event: event }, extra || {}) };
}
function statusPayload(extra) {
    return { topic: 'bsf/ac/status', payload: Object.assign({ ts: iso() }, extra || {}) };
}
function anomalyPayload(reason, extra) {
    return { topic: 'bsf/ac/anomaly', payload: Object.assign({ ts: iso(), reason: reason, source: 'ac_dispatcher_v18' }, extra || {}) };
}

// hw_status pipe: cache soc, hw drawing flag, ac_load, sunrise/sunset on flow context.
if (msg.topic === 'inside_temp' || msg.topic === 'bsf/ac/inside_temp') {
    var rawT = msg.payload;
    var valT;
    if (typeof rawT === 'number') { valT = rawT; }
    else if (rawT && typeof rawT === 'object' && typeof rawT.value === 'number') { valT = rawT.value; }
    else if (typeof rawT === 'string') { valT = parseFloat(rawT); }
    if (typeof valT === 'number' && isFinite(valT)) {
        flow.set('ac_inside_temp', valT);
        flow.set('ac_inside_temp_ts', Date.now());
    }
    return null;
}

// v1.11 (2026-06-17 Steven): LAN presence feed. Cache anyone_home + a heartbeat ts
// so the tick path can gate AUTO heating and detect a dead detector. Read-only: this
// only OBSERVES presence; it never affects PV / surplus / load math.
if (msg.topic === 'bsf/presence/state' || msg.topic === 'presence_state') {
    var pr = msg.payload;
    if (typeof pr === 'string') { try { pr = JSON.parse(pr); } catch (e) { pr = null; } }
    if (pr && typeof pr === 'object' && typeof pr.anyone_home === 'boolean') {
        flow.set('ac_anyone_home', pr.anyone_home);
        // configured = at least one phone registered. Unconfigured -> AUTO fails OPEN
        // (no roster must never brick heating). Absent field defaults to configured.
        flow.set('ac_presence_configured', pr.configured !== false);
        flow.set('ac_presence_ts', Date.now());
    }
    return null;
}

// v1.10.2 (2026-06-17 Steven): live control from the dashboard. Arrives on bsf/ac/cmd
// over MQTT (the LAN dashboard publishes over MQTT-over-WS). Validated SERVER-SIDE;
// never trusts the client. Writes flow context that the next tick reads; no redeploy.
//   action: 'set_thresholds'  -> inside-temp ON/OFF setpoints (range clamp + 0.5C snap + hysteresis)
//   action: 'set_mode'        -> AUTO | ON | OFF  (v1.11)
if (msg.topic === 'bsf/ac/cmd' || msg.topic === 'set_thresholds' || msg.topic === 'set_mode') {
    var body = msg.payload;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
    if (!body || typeof body !== 'object') {
        return [ null, logPayload('cmd_ignored', { reason: 'bad_payload' }), null, null ];
    }

    // ---- v1.11: AUTO/ON/OFF mode switch ----
    if (body.action === 'set_mode') {
        var m = (typeof body.mode === 'string') ? body.mode.toUpperCase() : '';
        if (m !== 'AUTO' && m !== 'ON' && m !== 'OFF') {
            return [ null, logPayload('cmd_ignored', { reason: 'bad_mode', mode: body.mode }), null, null ];
        }
        var srcM = (typeof body.source === 'string') ? body.source.slice(0, 40) : 'dashboard';
        flow.set('ac_mode', m);
        flow.set('ac_mode_changed_ts', Date.now());
        flow.set('ac_mode_changed_src', srcM);
        flow.set('ac_mode_off_sent', false);       // re-arm the OFF-guard log latch
        flow.set('ac_presence_off_sent', false);    // re-arm the presence-guard log latch
        if (m === 'OFF') {
            // hard override takes effect immediately — don't wait for the next tick.
            context.set('acState', 'off'); context.set('onSince', null); context.set('offSince', null);
            flow.set('ac_mode_off_sent', true);
            return [ plugCmd(false), logPayload('mode_set', { mode: m, source: srcM, action_taken: 'force_off' }), null, null ];
        }
        return [ null, logPayload('mode_set', { mode: m, source: srcM }), null, null ];
    }

    // ---- set_thresholds (v1.10.2) ----
    if (body.action !== 'set_thresholds') {
        return [ null, logPayload('cmd_ignored', { reason: 'unknown_action', action: body.action }), null, null ];
    }
    var cur0 = getThresholds();
    var reqOn  = Number(body.on_c),  reqOff = Number(body.off_c);
    if (!isFinite(reqOn))  reqOn  = cur0.on;
    if (!isFinite(reqOff)) reqOff = cur0.off;
    var on  = clampStep(reqOn,  INSIDE_TEMP_ON_MIN,  INSIDE_TEMP_ON_MAX);
    var off = clampStep(reqOff, INSIDE_TEMP_OFF_MIN, INSIDE_TEMP_OFF_MAX);
    // heating hysteresis: OFF >= ON + gap. Lift OFF first; if it caps out, drop ON.
    if (off < on + INSIDE_TEMP_MIN_GAP) {
        off = clampStep(on + INSIDE_TEMP_MIN_GAP, INSIDE_TEMP_OFF_MIN, INSIDE_TEMP_OFF_MAX);
        if (off < on + INSIDE_TEMP_MIN_GAP) {
            on = clampStep(off - INSIDE_TEMP_MIN_GAP, INSIDE_TEMP_ON_MIN, INSIDE_TEMP_ON_MAX);
        }
    }
    var changedTs = Date.now();
    var src = (typeof body.source === 'string') ? body.source.slice(0, 40) : 'dashboard';
    flow.set('ac_inside_temp_on_c', on);
    flow.set('ac_inside_temp_off_c', off);
    flow.set('ac_thresholds_changed_ts', changedTs);
    flow.set('ac_thresholds_changed_src', src);
    flow.set('ac_temp_off_sent', false);   // re-arm the temp-off log latch for the new band
    return [ null,
        logPayload('thresholds_set', { on_c: on, off_c: off, req_on: body.on_c, req_off: body.off_c, source: src }),
        null, null ];
}

if (msg.topic === 'hw_status') {
    var p = msg.payload || {};
    if (typeof p.soc === 'number') flow.set('ac_soc', p.soc);
    // HW is "drawing" if plug_power is meaningfully above zero (element active).
    if (typeof p.plug_power === 'number') {
        flow.set('ac_hw_drawing', p.plug_power > HW_DRAWING_THRESHOLD_W);
        flow.set('ac_hw_plug_power', p.plug_power);
    }
    // Also cache dispatcher's commanded hwState as a fallback signal.
    if (typeof p.hwState === 'string') flow.set('ac_hw_state', p.hwState);
    if (typeof p.ac_load === 'number') flow.set('ac_ac_load', p.ac_load);
    if (p.sunrise_iso) flow.set('ac_sunrise_iso', p.sunrise_iso);
    if (p.sunset_iso)  flow.set('ac_sunset_iso',  p.sunset_iso);
    return null;
}

// 5-min force-OFF outside any window (also force-OFF whenever ac_mode === 'OFF').
if (msg.topic === 'lockout_tick') {
    var winNow = flow.get('ac_window') || 'LOCKOUT';
    var modeNow = getMode();
    if (winNow === 'LOCKOUT' || modeNow === 'OFF') {
        return [ plugCmd(false), logPayload('lockout_force_off', { window: winNow, mode: modeNow }), null, null ];
    }
    return null;
}

if (msg.topic !== 'tick') return null;

var t = nowMs();
var d = new Date();
var hourFrac = d.getHours() + d.getMinutes()/60;

var soc        = flow.get('ac_soc');
// hwDrawing = HW element is actively pulling power, OR dispatcher commanded ON (belt + braces).
var hwDrawing  = !!flow.get('ac_hw_drawing') || (flow.get('ac_hw_state') === 'on');
var hwPlugPower= flow.get('ac_hw_plug_power');
var acLoad     = flow.get('ac_ac_load');
var insideTemp = flow.get('ac_inside_temp');
var insideTempTs = flow.get('ac_inside_temp_ts') || 0;
var insideTempStale = (Date.now() - insideTempTs) > INSIDE_TEMP_STALE_MS;
var insideTempUsable = typeof insideTemp === 'number' && isFinite(insideTemp) && !insideTempStale;
var _th = getThresholds();
var INSIDE_TEMP_ON_C = _th.on, INSIDE_TEMP_OFF_C = _th.off;

// v1.11: mode + presence
var acMode      = getMode();
var anyoneHome  = !!flow.get('ac_anyone_home');
var presenceTs  = flow.get('ac_presence_ts') || 0;
var presenceConfigured = flow.get('ac_presence_configured') !== false;   // unconfigured roster -> fail open
var presenceFresh = presenceTs > 0 && (Date.now() - presenceTs) <= PRESENCE_STALE_MS;
var presenceKnown = presenceFresh && presenceConfigured;

var sunsetISO  = flow.get('ac_sunset_iso');
var sunriseISO = flow.get('ac_sunrise_iso');
var sunset  = sunsetISO  ? Date.parse(sunsetISO)  : null;
var sunrise = sunriseISO ? Date.parse(sunriseISO) : null;
if (!sunset  || isNaN(sunset))  sunset  = new Date(d.getFullYear(),d.getMonth(),d.getDate(),17,30,0).getTime();
if (!sunrise || isNaN(sunrise)) sunrise = new Date(d.getFullYear(),d.getMonth(),d.getDate(), 6, 0,0).getTime();
var dispatchEnd  = sunset  - DISPATCH_END_OFFSET_MS;
var preHeatStart = sunrise - W1_PRE_SUNRISE_OFFSET_MS;

var windowName = 'LOCKOUT', onPct = null, offPct = null, requireHwOff = false;
if (t >= preHeatStart && hourFrac < W1_END_H) {
    windowName = 'W1_PRE_8'; onPct = W1_ON_PCT; offPct = W1_OFF_PCT;
} else if (hourFrac >= W1_END_H && hourFrac < W2_END_H) {
    windowName = 'W2_8_TO_13'; onPct = W2_ON_PCT; offPct = W2_OFF_PCT; requireHwOff = true;
} else if (hourFrac >= W2_END_H && t < dispatchEnd) {
    windowName = 'W3_13_TO_SUNSET_M2H'; onPct = W3_ON_PCT; offPct = W3_OFF_PCT; requireHwOff = true;
}
flow.set('ac_window', windowName);

var acState  = context.get('acState')  || 'off';
var onSince  = context.get('onSince')  || null;
var offSince = context.get('offSince') || null;

var statusMsg = statusPayload({
    window: windowName, acState: acState, soc: soc,
    hw_drawing: hwDrawing, hw_plug_power: hwPlugPower, ac_load: acLoad,
    on_pct: onPct, off_pct: offPct, require_hw_off: requireHwOff,
    inside_temp_on_c: INSIDE_TEMP_ON_C, inside_temp_off_c: INSIDE_TEMP_OFF_C,
    thresholds_changed_ts: flow.get('ac_thresholds_changed_ts') || null,
    thresholds_changed_src: flow.get('ac_thresholds_changed_src') || null,
    // v1.11 mode + presence
    ac_mode: acMode,
    anyone_home: anyoneHome,
    presence_known: presenceKnown,
    presence_configured: presenceConfigured && presenceFresh,
    presence_ts: presenceTs || null,
    mode_changed_ts: flow.get('ac_mode_changed_ts') || null,
    mode_changed_src: flow.get('ac_mode_changed_src') || null,
    dispatch_end_iso: new Date(dispatchEnd).toISOString(),
    preheat_start_iso: new Date(preHeatStart).toISOString()
});

// v1.11: ac_mode === 'OFF' — HARD OVERRIDE. Force the plug OFF every tick. Beats
// window, temp, SOC, presence and any manual ON. Highest priority gate.
if (acMode === 'OFF') {
    var wasOnOff = (acState === 'on');
    context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
    var offSent = flow.get('ac_mode_off_sent');
    flow.set('ac_mode_off_sent', true);
    if (!offSent || wasOnOff) {
        return [ plugCmd(false), logPayload(wasOnOff ? 'OFF' : 'OFF_mode_guard', { reason: 'ac_mode_off', was_on: wasOnOff, window: windowName }), statusMsg, null ];
    }
    return [ plugCmd(false), null, statusMsg, null ];
}
flow.set('ac_mode_off_sent', false);   // not in OFF mode — re-arm the latch

if (windowName === 'LOCKOUT') {
    if (acState === 'on') {
        context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
        return [ plugCmd(false), logPayload('OFF', { reason: 'LOCKOUT' }), statusMsg, null ];
    }
    return [ null, null, statusMsg, null ];
}

// Cascade safety trip: AC load is still too high AND HW is NOT drawing — kill AC.
// (If HW is still drawing, HW dispatcher will handle the safety cap; we wait.)
if (typeof acLoad === 'number' && acLoad > AC_SAFETY_W && !hwDrawing && acState === 'on') {
    context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
    var anomalyMsg = anomalyPayload('ac_load_above_safety_cap_hw_not_drawing', { ac_load: Math.round(acLoad), cap: AC_SAFETY_W, hw_plug_power: hwPlugPower });
    return [ plugCmd(false), logPayload('OFF', { reason: 'cascade_safety', ac_load: Math.round(acLoad), cap: AC_SAFETY_W, hw_plug_power: hwPlugPower, window: windowName }), statusMsg, anomalyMsg ];
}

// v1.10.1 (2026-06-05 Steven, option A): inside-temp OFF gate fires regardless of
// internal acState — guarantees a manual plug-ON gets corrected on the next tick.
// To avoid log spam every tick while warm, the log/anomaly only fires on the first
// tick of each warm cycle (tracked via flow flag ac_temp_off_sent).
if (insideTempUsable && insideTemp >= INSIDE_TEMP_OFF_C) {
    var wasOn = (acState === 'on');
    context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
    var alreadySent = flow.get('ac_temp_off_sent');
    flow.set('ac_temp_off_sent', true);
    if (!alreadySent || wasOn) {
        var logEv = wasOn ? 'OFF' : 'OFF_temp_guard';
        return [ plugCmd(false), logPayload(logEv, { reason: 'inside_temp_at_or_above_off_c', inside_temp: insideTemp, off_c: INSIDE_TEMP_OFF_C, was_on: wasOn, window: windowName }), statusMsg, null ];
    }
    // Subsequent ticks while still warm: silent OFF command (idempotent on Tuya plug).
    return [ plugCmd(false), null, statusMsg, null ];
} else if (insideTempUsable && insideTemp < INSIDE_TEMP_OFF_C) {
    flow.set('ac_temp_off_sent', false);
}

// v1.11: AUTO presence gate — nobody home forces OFF (the detector's 5-min grace has
// already elapsed before anyone_home goes false). Fails OPEN when the presence feed is
// stale (presenceKnown=false) so a detector outage can't strand the house cold. ON and
// OFF modes skip this entirely (OFF already returned above; ON ignores presence).
if (acMode === 'AUTO' && presenceKnown && !anyoneHome) {
    var wasOnPr = (acState === 'on');
    context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
    var prSent = flow.get('ac_presence_off_sent');
    flow.set('ac_presence_off_sent', true);
    if (!prSent || wasOnPr) {
        return [ plugCmd(false), logPayload(wasOnPr ? 'OFF' : 'OFF_presence_guard', { reason: 'nobody_home_auto', was_on: wasOnPr, window: windowName }), statusMsg, null ];
    }
    return [ plugCmd(false), null, statusMsg, null ];
}
flow.set('ac_presence_off_sent', false);   // home / ON / unknown — re-arm the latch

// v1.9 (2026-06-04 Steven): HW-exclusive priority removed. AC and HW can co-exist
// as long as combined load stays under AC_CAP_W / AC_SAFETY_W. HW dispatcher's own
// ac_load > 4200W trip catches overload first; v1.8 cascade safety below is the
// final guard. With 13.5 kW of panels, running both ~3.4 kW of devices is comfortable.

if (typeof soc !== 'number') {
    return [ null, null, statusMsg, null ];
}

if (acState === 'off') {
    var tempOk = insideTempUsable && insideTemp < INSIDE_TEMP_ON_C;   // v1.10
    // v1.11: AUTO requires someone home; ON ignores presence; a stale feed fails open.
    var presenceOk = (acMode === 'ON') || !presenceKnown || anyoneHome;
    var canOn = (soc >= onPct) && !(typeof acLoad === 'number' && acLoad > AC_SAFETY_W) && tempOk && presenceOk;
    if (canOn) {
        if (!onSince) { onSince = t; context.set('onSince', t); }
        if ((t - onSince) >= SUSTAIN_ON_MS) {
            context.set('acState','on'); context.set('onSince', null); context.set('offSince', null);
            return [ plugCmd(true), logPayload('ON', { window: windowName, soc: soc, on_pct: onPct, mode: acMode }), statusMsg, null ];
        }
    } else {
        context.set('onSince', null);
    }
    return [ null, null, statusMsg, null ];
} else {
    if (soc < offPct) {
        if (!offSince) { offSince = t; context.set('offSince', t); }
        if ((t - offSince) >= SUSTAIN_OFF_MS) {
            context.set('acState','off'); context.set('onSince', null); context.set('offSince', null);
            return [ plugCmd(false), logPayload('OFF', { window: windowName, soc: soc, off_pct: offPct }), statusMsg, null ];
        }
    } else {
        context.set('offSince', null);
    }
    return [ null, null, statusMsg, null ];
}
